     JSON_OBJECT('name','userData','label','透传信息','type','string','maximum',1024)))),
 JSON_ARRAY(JSON_OBJECT('match','all','conditions',JSON_ARRAY(
   JSON_OBJECT('field','options.segmentType','operator','neq','value','SolidColorSeg')),
