    'minimum',0,'maximum',1,'materialRole','reference_video',
    'formats',JSON_EXTRACT(@tencent_ci_video_formats,'$'),'maxDurationSeconds',2700,
    'items',JSON_OBJECT('name','videoId','type','integer')),
