-- Agnes image models installed before the structured capability baseline need the text-only business links after backfill.
INSERT INTO aid_ai_business_model_binding
  (func_code, model_id, capability_code, default_capability, defaults_json, sort_order, create_time, create_by)
SELECT b.func_code, b.model_id, 'text_to_image', 0, NULL, b.sort_order + 1, NOW(), 'upgrade'
FROM aid_ai_business_model_binding b
JOIN aid_ai_model m ON m.id=b.model_id
JOIN aid_ai_model_capability c ON c.model_id=m.id AND c.capability_code='text_to_image'
WHERE m.model_code IN ('agnes-image-2.0-flash','agnes-image-2.1-flash')
  AND m.del_flag='0'
  AND b.func_code IN ('main_character_image','main_scene_image','main_prop_image')
  AND b.capability_code='image_to_image'
  AND JSON_UNQUOTE(JSON_EXTRACT(c.definition_json,'$.enabled'))='true'
  AND NOT EXISTS (SELECT 1 FROM aid_ai_business_model_binding x
    WHERE x.func_code=b.func_code AND x.model_id=b.model_id AND x.capability_code='text_to_image');
-- Keep the legacy route identifiers in upgraded databases; bind missing aliases to the route actually present.
INSERT INTO aid_ai_model_alias
  (legacy_model_id,legacy_model_code,model_id,capability_code,binding_code,create_time,create_by)
SELECT m.id,m.model_code,m.id,'image_to_video',b.binding_code,NOW(),'upgrade'
FROM aid_ai_model m
JOIN aid_ai_provider p ON p.id=m.provider_id AND p.provider_code='volcengine'
JOIN aid_ai_model_protocol_binding b ON b.model_id=m.id
  AND b.capability_code='image_to_video'
  AND b.binding_code IN ('seedance_official_14','seedance_official_98','route_14','route_98')
WHERE m.model_code IN ('doubao-seedance-2.0','doubao-seedance-2.0-fast')
  AND m.del_flag='0'
  AND NOT EXISTS (SELECT 1 FROM aid_ai_model_alias a
    WHERE a.legacy_model_id=m.id OR a.legacy_model_code=m.model_code);

-- Older Agnes aliases can be left pointing at a removed binding after a partial model migration.
-- Repair only such orphaned aliases; keep valid operator-selected routes untouched.
UPDATE aid_ai_model_alias a
JOIN aid_ai_model m ON m.id=a.model_id
JOIN aid_ai_provider p ON p.id=m.provider_id AND p.provider_code='agnes'
JOIN aid_ai_model_protocol_binding b ON b.model_id=m.id
  AND b.capability_code=a.capability_code
  AND b.binding_code=CASE m.model_code
    WHEN 'agnes-video-2.5' THEN 'route_116'
    WHEN 'agnes-video-2.5-flash' THEN 'route_117' ELSE '' END
LEFT JOIN aid_ai_model_protocol_binding current_binding
  ON current_binding.model_id=m.id
  AND current_binding.capability_code=a.capability_code
  AND current_binding.binding_code=a.binding_code
SET a.binding_code=b.binding_code,a.update_time=NOW(),a.update_by='system'
WHERE m.model_code IN ('agnes-video-2.5','agnes-video-2.5-flash')
  AND m.del_flag='0' AND current_binding.id IS NULL;
-- The Mini price seed above runs after the route seed: copy the first-run price into new routes.
UPDATE aid_ai_model_protocol_binding b
JOIN aid_ai_model m ON m.id=b.model_id
JOIN aid_ai_provider p ON p.id=m.provider_id AND p.provider_code='volcengine'
SET b.definition_json=JSON_SET(b.definition_json,
      '$.billingMode',m.billing_mode,
      '$.billingRule',JSON_EXTRACT(m.billing_rule_json,'$'),
      '$.costCredits',m.cost_credits),
    b.update_time=NOW(),b.update_by='system'
WHERE m.model_code='doubao-seedance-2.0-mini' AND m.del_flag='0'
  AND b.protocol='seedance-video'
  AND JSON_VALID(b.definition_json)=1
  AND JSON_VALID(m.billing_rule_json)=1
  AND JSON_CONTAINS_PATH(b.definition_json,'one','$.billingRule')=0;
-- On pre-structured installations, the legacy image-input flag can remain false even when
-- an officially configured text route supports image content. Preserve administrator edits.
UPDATE aid_ai_model m
JOIN aid_ai_provider p ON p.id=m.provider_id
SET m.supports_image_input=1,
    m.config_version=COALESCE(m.config_version,0)+1,
    m.update_time=NOW(),m.update_by='system'
WHERE m.del_flag='0' AND m.supports_image_input=0 AND m.update_by='system'
  AND ((p.provider_code='dashscope' AND m.model_code IN ('qwen3.7-max','qwen3.7-plus'))
    OR (p.provider_code='gemini' AND m.model_code IN
      ('gemini-3-flash-preview','gemini-3.1-flash-lite','gemini-3.1-pro-preview','gemini-3.5-flash'))
    OR (p.provider_code='openai' AND m.model_code IN ('gpt-5.4','gpt-5.5','gpt-5.6')))
  AND EXISTS (SELECT 1 FROM aid_ai_model_protocol_binding b
    WHERE b.model_id=m.id AND b.capability_code='text'
      AND JSON_VALID(b.definition_json)=1
      AND JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.capability.supportsImageInput'))='true');
-- Restore a legacy ID only when it is unclaimed and the alias still points to its canonical model.
DROP TEMPORARY TABLE IF EXISTS tmp_aid_alias_identity_seed;
