 legacy_model_id BIGINT NOT NULL, legacy_model_code VARCHAR(100) NOT NULL,
 provider_code VARCHAR(100) NOT NULL, model_code VARCHAR(120) NOT NULL,
 PRIMARY KEY (legacy_model_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
