INSERT INTO aid_ai_business_model_binding
 (func_code,model_id,capability_code,default_capability,defaults_json,sort_order,create_time,create_by)
SELECT f.func_code,m.id,s.capability_code,s.default_capability,s.defaults_json,s.sort_order,NOW(),'upgrade'
FROM tmp_aid_business_seed s
JOIN aid_ai_model_func_config f ON f.func_code=s.func_code AND f.del_flag='0'
JOIN aid_ai_provider p ON p.provider_code=s.provider_code AND p.del_flag='0'
JOIN aid_ai_model m ON m.provider_id=p.id AND m.model_code=s.model_code AND m.del_flag='0'
JOIN aid_ai_model_capability c ON c.model_id=m.id AND c.capability_code=s.capability_code
WHERE JSON_VALID(f.model_ids)=1
 AND (JSON_CONTAINS(f.model_ids,CAST(m.id AS CHAR))=1
   OR EXISTS (SELECT 1 FROM aid_ai_model_alias alias_row
     WHERE alias_row.model_id=m.id
       AND NOT EXISTS (SELECT 1 FROM aid_ai_model claimed
         WHERE claimed.id=alias_row.legacy_model_id AND claimed.del_flag='0' AND claimed.id<>m.id)
       AND JSON_CONTAINS(f.model_ids,CAST(alias_row.legacy_model_id AS CHAR))=1))
 AND JSON_UNQUOTE(JSON_EXTRACT(c.definition_json,'$.enabled'))='true'
 AND NOT EXISTS (SELECT 1 FROM aid_ai_business_model_binding existing
   WHERE existing.func_code=f.func_code AND existing.model_id=m.id);
DROP TEMPORARY TABLE IF EXISTS tmp_aid_business_seed;
